<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-safe">
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'RequestAyda' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 truncate font-medium text-ui-ink-gray-900"
					>Tambah Request AYDA Motor</span
				>
			</div>
		</div>

		<div class="flex flex-1 flex-col">
			<p v-if="!metaFields.length && !metaError" class="px-6 py-4 text-sm text-ui-ink-gray-500">
				Memuat form…
			</p>
			<pre
				v-else-if="metaError"
				class="px-6 py-4 text-sm text-ui-ink-red-600 whitespace-pre-wrap"
				>{{ metaError }}</pre
			>

			<div v-else class="app-container-narrow px-4 py-5 text-base md:px-6">
				<pre
					v-if="saveError"
					class="mb-4 rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm text-ui-ink-red-700 whitespace-pre-wrap"
					>{{ saveError }}</pre
				>

				<div class="space-y-4">
					<!-- Header fields (meta-driven, kecuali child table units) -->
					<section
						class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
					>
						<div class="space-y-4">
							<div v-for="field in headerFields" :key="field.fieldname">
								<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
									{{ field.label }}
									<span v-if="field.reqd" class="text-ui-ink-red-500">*</span>
								</label>

								<template v-if="field.read_only">
									<p class="min-h-[1.25rem] break-words text-base text-ui-ink-gray-800">
										{{
											form[field.fieldname] == null ||
											form[field.fieldname] === ''
												? '—'
												: form[field.fieldname]
										}}
									</p>
								</template>

								<template v-else>
									<input
										v-if="field.fieldtype === 'Date'"
										v-model="form[field.fieldname]"
										type="date"
										:class="inputClass"
									/>
									<textarea
										v-else-if="
											['Small Text', 'Text', 'Long Text'].includes(
												field.fieldtype
											)
										"
										v-model="form[field.fieldname]"
										rows="3"
										:class="[inputClass, 'resize-none']"
									/>
									<!-- Link (cabang) → dropdown searchable -->
									<div v-else-if="field.fieldtype === 'Link'" class="relative">
										<button
											type="button"
											:class="[
												inputClass,
												'flex items-center justify-between gap-2 text-left',
											]"
											@click="toggleLinkDropdown(field)"
										>
											<span class="min-w-0 truncate font-bold text-ui-ink-gray-900">
												{{ form[field.fieldname] || 'Pilih…' }}
											</span>
											<svg
												xmlns="http://www.w3.org/2000/svg"
												viewBox="0 0 24 24"
												class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
												fill="none"
												stroke="currentColor"
												stroke-width="2"
												stroke-linecap="round"
												stroke-linejoin="round"
											>
												<path d="m6 9 6 6 6-6" />
											</svg>
										</button>
										<div
											v-if="openDropdown === field.fieldname"
											class="absolute left-0 right-0 z-30 mt-1.5 overflow-hidden rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-xl ring-1 ring-black/5"
										>
											<div class="border-b border-ui-line-gray-100 p-2">
												<input
													v-model="linkSearch"
													type="text"
													placeholder="Cari…"
													:class="inputClass"
													@click.stop
													@input="onLinkSearch(field)"
												/>
											</div>
											<div class="max-h-56 overflow-y-auto p-1">
												<button
													v-for="opt in linkResults"
													:key="opt"
													type="button"
													class="flex w-full items-start rounded-lg px-3 py-2 text-left font-bold text-ui-ink-gray-900 transition hover:bg-ui-surface-gray-50"
													@click="selectLink(field, opt)"
												>
													{{ opt }}
												</button>
												<p
													v-if="!linkResults.length"
													class="px-3 py-2 text-xs text-ui-ink-gray-400"
												>
													{{
														linkSearchLoading
															? 'Mencari…'
															: 'Tidak ada hasil'
													}}
												</p>
											</div>
										</div>
									</div>
									<input
										v-else
										v-model="form[field.fieldname]"
										type="text"
										:class="inputClass"
									/>
								</template>
							</div>
						</div>
					</section>

					<!-- Child table units → kartu collapsible -->
					<section>
						<h2 class="mb-1 pl-4 text-lg font-semibold text-primary md:pl-5">
							List Unit <span class="text-ui-ink-red-500">*</span>
						</h2>
						<p class="mb-3 pl-4 text-xs text-ui-ink-gray-400 md:pl-5">
							{{
								form.cabang
									? 'Pilih Motor Tarikan; data unit terisi otomatis.'
									: 'Pilih Cabang dulu untuk memfilter unit.'
							}}
						</p>
						<AydaUnitCards
							v-model="form.units"
							:editable="true"
							:cabang="form.cabang || ''"
						/>
					</section>
				</div>

				<div v-if="openDropdown" class="fixed inset-0 z-10" @click="openDropdown = ''" />
			</div>
		</div>

		<div
			class="sticky bottom-0 z-20 flex gap-2 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
		>
			<RouterLink
				:to="{ name: 'RequestAyda' }"
				class="flex flex-1 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface py-2.5 text-sm font-medium text-ui-ink-gray-700"
			>
				Cancel
			</RouterLink>
			<button
				type="button"
				:disabled="saving"
				class="flex flex-1 items-center justify-center rounded-lg bg-primary py-2.5 text-sm font-medium text-ui-onPrimary transition hover:opacity-90 disabled:opacity-50"
				@click="submit"
			>
				{{ saving ? 'Menyimpan…' : 'Save' }}
			</button>
		</div>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'
import AydaUnitCards from '../components/AydaUnitCards.vue'

const router = useRouter()
const DOCTYPE = 'Request AYDA Motor'

const form = reactive({ tanggal_request: today(), units: [] })
const saving = ref(false)
const saveError = ref('')
const metaFields = ref([])
const metaError = ref('')

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

function today() {
	const d = new Date()
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
		d.getDate()
	).padStart(2, '0')}`
}
function isNullVal(v) {
	return v == null || v === ''
}

// Field header yang tampil: bukan Section/Column Break, bukan child Table (ditangani
// AydaUnitCards), bukan hidden, dan read_only kosong disembunyikan (spt form desk).
const headerFields = computed(() =>
	metaFields.value.filter((f) => {
		if (
			[
				'Section Break',
				'Column Break',
				'HTML',
				'Button',
				'Heading',
				'Table',
				'Attach',
				'Attach Image',
			].includes(f.fieldtype)
		)
			return false
		if (f.hidden) return false
		if (f.read_only && isNullVal(form[f.fieldname])) return false
		return true
	})
)

async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (dt && dt.fields) || []
	} catch (e) {
		metaError.value = e.message || String(e)
	}
}

// ---- Link dropdown (cabang) ----
const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
let linkSearchTimer = null

function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	fetchLinkResults(field, '')
}
async function fetchLinkResults(field, query) {
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const params = new URLSearchParams({
			doctype: field.options,
			fields: JSON.stringify(['name']),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		if (query) params.set('filters', JSON.stringify([['name', 'like', `%${query}%`]]))
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		if (!res.ok) throw new Error((json && json.exception) || `HTTP ${res.status}`)
		linkResults.value = (json.message || []).map((r) => String(r.name))
	} catch (e) {
		linkResults.value = []
		notifyError(e, 'Gagal memuat pilihan')
	} finally {
		linkSearchLoading.value = false
	}
}
function onLinkSearch(field) {
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, linkSearch.value.trim()), 300)
}
function selectLink(field, value) {
	const prev = form[field.fieldname]
	form[field.fieldname] = value
	openDropdown.value = ''
	// Ganti cabang → kosongkan unit (unit terfilter per cabang, seperti desk).
	if (field.fieldname === 'cabang' && prev && prev !== value) form.units = []
}

function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

function validate() {
	const missing = []
	if (!form.cabang) missing.push('Cabang')
	if (!form.tanggal_request) missing.push('Tanggal Request')
	const validUnits = (form.units || []).filter((u) => u.motor_tarikan)
	if (!validUnits.length) missing.push('minimal 1 unit (List Unit)')
	return missing
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi: ${missing.join(', ')}`
		notifyError(saveError.value, 'Data belum lengkap')
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		const units = (form.units || [])
			.filter((u) => u.motor_tarikan)
			.map((u) => ({ doctype: 'Request AYDA Motor Item', ...u }))
		const doc = { doctype: DOCTYPE, ...form, units }
		const res = await fetch('/api/method/frappe.client.insert', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		notifySuccess('Request AYDA Motor berhasil dibuat.')
		const name = json.message?.name
		if (name) router.push({ name: 'RequestAydaDetail', params: { name } })
		else router.push({ name: 'RequestAyda' })
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	await loadMeta()
})
</script>
